import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, uv, positionLocal, normalLocal, uniform, mix, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    PlaneGeometry,
    IcosahedronGeometry,
    CircleGeometry,
    Color,
    PointLight,
    DoubleSide,
  } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'nova-features-ornamental-divider';

  const baseY = 0;
  const baseScale = 1;

  // --- soft engineered-gradient glow plate (rear depth plane) -----------
  const glowGeo = new PlaneGeometry(3.0, 0.5, 1, 1);
  const glowMat = new MeshStandardNodeMaterial({
    roughness: 1,
    metalness: 0,
    transparent: true,
    opacity: 0.35,
  });
  const cInk = new Color(colors.ink);
  const cSurface = new Color(colors.surface);
  glowMat.colorNode = mix(
    vec3(cSurface.r, cSurface.g, cSurface.b),
    vec3(cInk.r, cInk.g, cInk.b),
    uv().y
  );
  const glowMesh = new Mesh(glowGeo, glowMat);
  glowMesh.position.set(0, 0, -0.06);
  group.add(glowMesh);

  // --- thin machined rule (tessellated, depth-map parallax) -------------
  const ruleGeo = new PlaneGeometry(2.6, 0.12, 64, 64);
  const ruleMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.ink),
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
    side: DoubleSide,
  });
  if ('anisotropy' in ruleMat) {
    ruleMat.anisotropy = 0.55;
    ruleMat.anisotropyRotation = Math.PI / 2;
  }
  const ruleMesh = new Mesh(ruleGeo, ruleMat);
  ruleMesh.position.set(0, 0, 0);
  group.add(ruleMesh);

  const dispAmount = uniform(0.05);
  let ruleTexture = null;
  let depthTexture = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      ruleTexture = tex;
      if (ctx.THREE.SRGBColorSpace) tex.colorSpace = ctx.THREE.SRGBColorSpace;
      const base = vec3(cInk.r, cInk.g, cInk.b);
      ruleMat.colorNode = mix(base, texture(tex, uv()), 0.85);
      ruleMat.needsUpdate = true;
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTexture = tex;
      const depthSample = texture(tex, uv()).r.sub(0.5);
      ruleMat.positionNode = positionLocal.add(
        normalLocal.mul(depthSample.mul(dispAmount))
      );
      ruleMat.needsUpdate = true;
    });
  }

  // --- center jewel -------------------------------------------------------
  const jewelGeo = new IcosahedronGeometry(0.09, 2);
  const cAccent = new Color(colors.accent);
  const jewelMat = new MeshPhysicalNodeMaterial({
    color: cAccent,
    metalness: 0.0,
    roughness: 0.06,
    transmission: 0.92,
    ior: 1.5,
    thickness: 0.06,
    clearcoat: 0.2,
    emissive: cAccent,
    emissiveIntensity: 1.3,
  });
  const jewelMesh = new Mesh(jewelGeo, jewelMat);
  jewelMesh.position.set(0, 0, 0.03);
  group.add(jewelMesh);

  // accent rim light behind jewel (node-local, within intensity cap)
  const rimLight = new PointLight(cAccent, 0.9, 2.2, 2);
  rimLight.position.set(0, 0, -0.6);
  group.add(rimLight);

  // small key-side accent to catch jewel facets
  const keyAccent = new PointLight(cAccent, 0.5, 1.6, 2);
  keyAccent.position.set(0.4, 0.3, 0.5);
  group.add(keyAccent);

  // --- contact shadow (grounding) -----------------------------------------
  const shadowGeo = new CircleGeometry(1.7, 48);
  const shadowMat = new MeshStandardNodeMaterial({
    color: new Color('#000000'),
    transparent: true,
    opacity: 0.45,
    roughness: 1,
    metalness: 0,
  });
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.set(0, -0.35, -0.02);
  group.add(shadowMesh);

  // --- subtle cursor/camera parallax primitive (required by spec) --------
  let parallaxRig = null;
  try {
    parallaxRig = ctx.primitives['magnetic-cursor']?.(group, {
      strength: 0.045,
      radius: 1.4,
      ease: 0.18,
    });
  } catch (e) {
    parallaxRig = null;
  }

  // apply any configured cinematic primitives (none declared, but honor contract)
  const appliedPrimitives = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const p of primitiveList) {
    const fn = ctx.primitives[p.name];
    if (typeof fn === 'function') {
      const result = fn(group, p.params ?? {});
      appliedPrimitives.push(result);
    }
  }

  group.position.set(config.scenePosition?.x ?? -1.25, config.scenePosition?.y ?? -0.2, config.scenePosition?.z ?? 0);

  // --- interaction handlers -------------------------------------------------
  let hoverTl = null;
  let pressTl = null;

  group.userData.handlers = {
    onPointerEnter: () => {
      hoverTl?.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(group.position, {
        y: baseY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
      hoverTl.to(
        group.scale,
        { x: 1.04, y: 1.04, z: 1.04, duration: 0.9, ease: 'power4.out' },
        0
      );
      hoverTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
    },
    onPointerLeave: () => {
      hoverTl?.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(group.position, {
        y: baseY,
        duration: 0.5,
        ease: 'power2.out',
      });
      hoverTl.to(
        group.scale,
        { x: baseScale, y: baseScale, z: baseScale, duration: 0.5, ease: 'power2.out' },
        0
      );
    },
    onPointerDown: () => {
      pressTl?.kill();
      pressTl = gsap.timeline();
      pressTl.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(2)',
      });
    },
    onPointerUp: () => {
      pressTl?.kill();
      pressTl = gsap.timeline();
      pressTl.to(group.scale, {
        x: baseScale,
        y: baseScale,
        z: baseScale,
        duration: 0.12,
        ease: 'back.out(2)',
      });
    },
    onClick: () => {
      ctx.emit('hub-features.select', { source: 'ornamental-divider' });
    },
  };

  // --- cleanup ---------------------------------------------------------------
  group.userData.cleanup = () => {
    hoverTl?.kill();
    pressTl?.kill();

    for (const p of appliedPrimitives) {
      p?.timeline?.kill?.();
      p?.cleanup?.();
    }
    if (parallaxRig) {
      parallaxRig.timeline?.kill?.();
      parallaxRig.cleanup?.();
    }

    glowGeo.dispose();
    glowMat.dispose();
    ruleGeo.dispose();
    ruleMat.dispose();
    jewelGeo.dispose();
    jewelMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();

    ruleTexture?.dispose?.();
    depthTexture?.dispose?.();

    rimLight.dispose?.();
    keyAccent.dispose?.();
  };

  return group;
}
